'use client';

import { FormEvent, useEffect, useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import type { AuthUser } from '@cdp/shared';
import { api, ApiClientError, type MemberOverview } from '@/lib/api';
import { Icon } from '@/components/icon';

type View = 'home' | 'camp' | 'profile';
type BookingDetails = { fullName: string; phone: string; group: 'Group 1' | 'Group 2' | 'Group 3' | 'Group 4' | 'Group 5' };
const money = (value: number) => new Intl.NumberFormat('en-GH', { style: 'currency', currency: 'GHS' }).format(value / 100);

export default function AccountPage(): React.JSX.Element {
  const router = useRouter(); const [view, setView] = useState<View>('home'); const [user, setUser] = useState<AuthUser | null>(null); const [overview, setOverview] = useState<MemberOverview | null>(null); const [error, setError] = useState<string | null>(null); const [notice, setNotice] = useState<string | null>(null); const [busy, setBusy] = useState<string | null>(null);
  async function load() { try { const [auth, member] = await Promise.all([api.me(), api.memberOverview()]); setUser(auth.user); setOverview(member); setError(null); } catch (err) { if (err instanceof ApiClientError && err.status === 401) router.replace('/login'); else setError('Could not load your member workspace. Please refresh and try again.'); } }
  useEffect(() => { void load(); }, []);
  async function book(campId: string, bedId: string, details: BookingDetails) { setBusy(bedId); setError(null); try { await api.bookBed({ campId, bedId, ...details }); setNotice('Your camp request has been sent for approval.'); await load(); } catch (err) { setError(err instanceof Error ? err.message : 'Could not reserve this option.'); } finally { setBusy(null); } }
  async function signOut() { setBusy('logout'); try { await api.logout(); window.dispatchEvent(new Event('auth-changed')); router.replace('/'); router.refresh(); } catch { setError('Could not sign out. Please try again.'); setBusy(null); } }
  async function changePassword(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy('password'); setError(null); setNotice(null); const form = new FormData(event.currentTarget); const newPassword = String(form.get('newPassword')); if (newPassword !== String(form.get('confirmPassword'))) { setError('The new passwords do not match.'); setBusy(null); return; } try { await api.changePassword({ currentPassword: String(form.get('currentPassword')), newPassword }); setNotice('Your password has been changed.'); event.currentTarget.reset(); } catch (err) { setError(err instanceof Error ? err.message : 'Could not change your password.'); } finally { setBusy(null); } }
  const firstName = user?.fullName.trim().split(/\s+/)[0] ?? 'Member'; const parts = user?.fullName.trim().split(/\s+/) ?? []; const canAdmin = user?.permissions.includes('*') || user?.permissions.includes('reports.read_all');
  return <div className="portal-shell member-portal-shell"><aside className="portal-sidebar member-portal-sidebar"><p className="portal-label">CITY MEGA CHURCH<br/>MEMBER PORTAL</p><nav aria-label="Member portal navigation"><button className={view === 'home' ? 'active' : ''} onClick={() => setView('home')} title="Overview"><Icon name="cross"/><span>Overview</span></button><button className={view === 'camp' ? 'active' : ''} onClick={() => setView('camp')} title="Camp booking"><Icon name="people"/><span>Camp booking</span></button><button className={view === 'profile' ? 'active' : ''} onClick={() => setView('profile')} title="My profile"><Icon name="user"/><span>My profile</span></button>{canAdmin && <Link className="member-admin-link" href="/admin"><Icon name="arrow-up"/><span>Admin portal</span></Link>}</nav></aside><main className="portal-main member-portal-main"><header className="portal-topbar"><div><p className="eyebrow">WELCOME, {firstName.toUpperCase()}</p><h1>{view === 'home' ? 'Your dashboard' : view === 'camp' ? 'Camp booking' : 'My profile'}</h1></div><div className="portal-user"><div className="portal-avatar">{user?.fullName.split(/\s+/).map(x=>x[0]).slice(0,2).join('') || 'ME'}</div><div><strong>{user?.fullName || 'Member'}</strong><button disabled={busy === 'logout'} onClick={() => void signOut()}><Icon name="logout" size={15}/> {busy === 'logout' ? 'Signing out…' : 'Sign out'}</button></div></div></header>{error && <p className="alert">{error}</p>}{notice && <p className="success-message">{notice}</p>}{!user || !overview ? <div className="workspace-loading">Preparing your dashboard…</div> : view === 'home' ? <Overview user={user} overview={overview} goCamp={() => setView('camp')} goProfile={() => setView('profile')} /> : view === 'camp' ? <CampBooking overview={overview} busy={busy} book={book} /> : <Profile user={user} firstName={parts[0] ?? ''} surname={parts.slice(1).join(' ') || '—'} busy={busy} changePassword={changePassword} />}</main></div>;
}

function Overview({ user, overview, goCamp, goProfile }: { user: AuthUser; overview: MemberOverview; goCamp: () => void; goProfile: () => void }) { const active=overview.booking && overview.booking.status !== 'declined'; return <div className="member-dashboard-grid"><article className="member-welcome-card"><div className="member-avatar">{user.fullName.split(/\s+/).map(x => x[0]).slice(0, 2).join('')}</div><div><span>{user.churchPosition || 'Member'}</span><h2>{user.fullName}</h2><p>Stay connected with the City Mega Church family and manage your activities from one place.</p><button onClick={goProfile}>View my profile <Icon name="arrow" /></button></div></article><article className="member-highlight"><p className="eyebrow">CAMP REGISTRATION</p>{active ? <><span className={`status status--${overview.booking!.status}`}>{overview.booking!.status}</span><h2>{overview.booking!.room}</h2><p>{overview.booking!.status === 'approved' ? 'Your camp place is confirmed. We look forward to welcoming you.' : 'Your request is with the camp team for review.'}</p></> : <>{overview.booking?.status === 'declined' && <span className="status status--declined">Previous request declined</span>}<h2>{overview.booking?.status === 'declined' ? 'Choose another place.' : 'Your next encounter starts here.'}</h2><p>{overview.booking?.status === 'declined' ? 'You can submit a new Villa, Hostel, or Dormitory request now.' : 'Choose a Villa, Hostel, or Dormitory place and send your request for approval.'}</p><button className="btn btn--cream" onClick={goCamp}>{overview.booking?.status === 'declined' ? 'Book another place' : 'Book a place'} <Icon name="arrow-up" /></button></>}</article><article className="member-quick-card"><Icon name="clock" /><div><strong>Sunday services</strong><span>8:00 AM and 11:00 AM</span></div></article><article className="member-quick-card"><Icon name="sun" /><div><strong>Bethel Experience</strong><span>Thursday · 7:00 PM</span></div></article></div>; }

function CampBooking({ overview, busy, book }: { overview: MemberOverview; busy: string | null; book: (campId: string, bedId: string, details: BookingDetails) => Promise<void> }) {
  const active = overview.booking && overview.booking.status !== 'declined';
  const [details, setDetails] = useState<BookingDetails | null>(null);
  function continueToRooms(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    setDetails({ fullName: String(form.get('fullName')).trim(), phone: String(form.get('phone')).trim(), group: String(form.get('group')) as BookingDetails['group'] });
  }
  if (active) return <section className="workspace-panel"><div className="workspace-panel-heading"><div><p className="eyebrow">CAMP ACCOMMODATION</p><h2>Your camp request.</h2></div><p>The camp team will keep this status updated.</p></div><div className="booking-confirmation"><div><span className={`status status--${overview.booking!.status}`}>{overview.booking!.status}</span><h3>{overview.booking!.room}</h3><p>{overview.booking!.campTitle} · {overview.booking!.location}</p></div><strong>{money(overview.booking!.pricePesewas)}</strong></div></section>;
  if (!overview.camps.length) return <section className="workspace-panel"><div className="portal-empty">Camp registration is currently closed. Please check back soon.</div></section>;
  return <section className="workspace-panel"><div className="workspace-panel-heading"><div><p className="eyebrow">CAMP REGISTRATION</p><h2>{details ? 'Choose your room.' : 'Tell us about you.'}</h2></div><p>{details ? 'Select Villa, Hostel, or Dormitory to submit your request.' : 'We need these details before you select an accommodation.'}</p></div>{overview.booking?.status === 'declined' && <p className="booking-retry-note">Your previous request was declined. You can complete the details below and choose another available option.</p>}{!details ? <form className="booking-details-form" onSubmit={continueToRooms}><label>Full name<input name="fullName" autoComplete="name" minLength={2} required placeholder="Your full name" /></label><label>Phone number<input name="phone" type="tel" autoComplete="tel" pattern="\+?[0-9]{9,15}" required placeholder="e.g. 0241234567" /></label><label>Church group<select name="group" required defaultValue=""><option value="" disabled>Select your group</option>{['Group 1','Group 2','Group 3','Group 4','Group 5'].map(group => <option key={group}>{group}</option>)}</select></label><button className="btn btn--primary">Continue to room selection <Icon name="arrow" size={17}/></button></form> : <><div className="booking-details-summary"><div><span>Booking for</span><strong>{details.fullName}</strong></div><div><span>Phone</span><strong>{details.phone}</strong></div><div><span>Group</span><strong>{details.group}</strong></div><button onClick={() => setDetails(null)}>Edit details</button></div>{overview.camps.map(camp => <div key={camp.id} className="camp-offer"><div className="camp-meta"><h3>{camp.title}</h3><p>{camp.description}</p><span><Icon name="pin" size={16}/> {camp.location}</span></div><div className="accommodation-grid">{camp.beds.slice(0,3).map((bed,index) => { const available=bed.bookedCount<bed.capacity; return <article key={bed.id} className={`accommodation-card accommodation-card--${index+1}`}><span className="accommodation-number">0{index+1}</span><p>{bed.label}</p><h4>{bed.room}</h4><strong>{money(bed.pricePesewas)}</strong><small>{Math.max(0,bed.capacity-bed.bookedCount)} places available</small><button disabled={!available||busy!==null} onClick={() => void book(camp.id,bed.id,details)}>{busy===bed.id?'Sending…':available?'Request this place':'Fully booked'} <Icon name="arrow" size={17}/></button></article>;})}</div></div>)}</>}</section>;
}

function Profile({ user, firstName, surname, busy, changePassword }: { user: AuthUser; firstName: string; surname: string; busy: string | null; changePassword: (event: FormEvent<HTMLFormElement>) => Promise<void> }) { return <div className="profile-layout"><section className="workspace-panel"><p className="eyebrow">PERSONAL INFORMATION</p><h2>Your profile</h2><p className="profile-note">These details identify your membership account. Contact the church office if a correction is needed.</p><div className="readonly-fields"><label>First name<input value={firstName} readOnly /></label><label>Second name<input value={surname} readOnly /></label><label className="wide">Email address<input value={user.email} readOnly /></label></div></section><section className="workspace-panel"><p className="eyebrow">ACCOUNT SECURITY</p><h2>Change password</h2><form className="security-form" onSubmit={changePassword}><label>Current password<input name="currentPassword" type="password" autoComplete="current-password" required /></label><label>New password<input name="newPassword" type="password" autoComplete="new-password" minLength={8} required /></label><label>Confirm new password<input name="confirmPassword" type="password" autoComplete="new-password" minLength={8} required /></label><button className="btn btn--primary" disabled={busy === 'password'}>{busy === 'password' ? 'Updating…' : 'Update password'}</button></form></section></div>; }
